import { WorkspaceSidebarSizeContext } from "../WorkspaceModeHeader";
import { openCommandPalette } from "../../commandPaletteBus";
import type { SidebarPeople } from "./upstream/SidebarPeopleSection";
/* oxlint-disable shadcn/no-unknown-classes -- OpenBot source selectors are provided by the explicitly imported scoped CSS, not generated by Tailwind. */
import { useContext, useState, type ReactNode } from "react";
import {
  SettingsIcon,
  SearchIcon,
  PanelRightIcon,
  ListTodoIcon,
  FilesIcon,
  MessageCircleIcon,
  MonitorIcon,
  SquarePenIcon,
  MoreHorizontalIcon,
  RefreshCwIcon,
  ChevronDownIcon,
  ArrowLeftIcon,
  ArrowRightIcon,
} from "lucide-react";
import type { EnvironmentId, OpenbotAgent, OpenbotChannelSummary } from "@t3tools/contracts";
import { cn } from "../../lib/utils";
import { Button } from "../ui/button";
import { Tooltip, TooltipTrigger, TooltipPopup } from "../ui/tooltip";
import { SourceAgentAvatar } from "./SourceAgentAvatar";
import { Menu, MenuTrigger, MenuItem, MenuPopup } from "../ui/menu";
import { TooltipProvider } from "./upstream/OpenbotTooltip";
import { OpenbotSidebar } from "./upstream/OpenbotSidebar";
import { OpenbotThreadTabs, type OpenbotThreadTabLayout } from "./upstream/OpenbotThreadTabs";
import "./upstream/openbot-react.css";
import "./sled-bots.css";
import { T, useGT } from "gt-react";
export type BotWorkspaceSection =
  | "direct"
  | "chats"
  | "flows"
  | "groups"
  | "workflows"
  | "tasks"
  | "schedule"
  | "marketplace"
  | "usage"
  | "attention"
  | "manage"
  | "settings"
  | "host-settings";
export type BotWorkspaceView =
  | "Chat"
  | "Tasks"
  | "Memory"
  | "Routines"
  | "Files"
  | "Browser"
  | "Computer"
  | "Data"
  | "Vault"
  | "Settings";
type Agent = typeof OpenbotAgent.Type;
// Important utilities fence the unlayered upstream styles inside the Sled workspace.
export function BotWorkspaceChrome({
  label,
  environmentId,
  hostId,
  section,
  view,
  bot,
  sidePanelHeader,
  sidePanelMaximized = false,
  onOpenSearch,
  tasks,
  selectedTaskId,
  onTask,
  onRenameTask,
  threadLayout,
  onThreadLayout,
  onMoveThreadToSide,
  onNewThread,
  newThread,
  onTogglePanel,
  agents,
  channels,
  people,
  selectedChannel,
  loading,
  onSection,
  onBot,
  onGroup,
  onView,
  onRefresh,
  canBack,
  canForward,
  onBack,
  onForward,
  children,
}: {
  label: string;
  environmentId: EnvironmentId;
  hostId: string | null;
  sidePanelHeader?: ReactNode;
  sidePanelMaximized?: boolean;
  onOpenSearch: () => void;
  tasks: readonly { id: string; title: string; state: string }[];
  selectedTaskId: string | null;
  onTask: (id: string | null) => void;
  onRenameTask: (id: string, title: string) => Promise<boolean>;
  threadLayout: OpenbotThreadTabLayout;
  onThreadLayout: (layout: OpenbotThreadTabLayout) => void;
  onMoveThreadToSide: (id: string) => void;
  onNewThread: () => void;
  newThread: boolean;
  onTogglePanel: () => void;
  section: BotWorkspaceSection;
  view: BotWorkspaceView;
  bot: Agent | undefined;
  agents: readonly Agent[];
  channels: readonly OpenbotChannelSummary[];
  people: SidebarPeople;
  selectedChannel: string | null;
  loading: boolean;
  onSection: (value: BotWorkspaceSection) => void;
  onBot: (id: string) => void;
  onGroup: (id: string) => void;
  onView: (view: BotWorkspaceView) => void;
  onRefresh: () => void;
  canBack: boolean;
  canForward: boolean;
  onBack: () => void;
  onForward: () => void;
  children: ReactNode;
}) {
  const gt = useGT();
  const [localWidth, setLocalWidth] = useState(288);
  const sharedSize = useContext(WorkspaceSidebarSizeContext);
  const width = sharedSize?.width ?? localWidth;
  const setWidth = (next: number) => (sharedSize ? sharedSize.resize(next) : setLocalWidth(next));
  const showSidebar =
    section === "chats" || section === "groups" || section === "flows" || section === "direct";
  const chooseTool = (next: BotWorkspaceView) => {
    onView(next);
  };
  const pageHeading: Partial<Record<BotWorkspaceSection, string>> = {
    workflows: "Workflows",
    tasks: "Tasks",
    schedule: "Schedule",
    marketplace: "Marketplace",
  };
  const heading =
    pageHeading[section] ??
    (section === "chats"
      ? (bot?.name ?? "Chats")
      : section === "groups"
        ? "Groups"
        : section === "flows"
          ? "Routines"
          : section === "usage"
            ? "Usage"
            : section === "attention"
              ? "Needs attention"
              : section === "settings"
                ? "Settings"
                : "New agent");
  return (
    <TooltipProvider>
      <div
        className={cn(
          "openbot-react ob-shell ob-sled-shell",
          "[&&]:bg-background! [&&]:p-0! [&&]:font-sans! [&&]:text-sm! [&&]:leading-normal! [&&]:overflow-visible!",
          "[&&_.ob-sidebar-card]:rounded-none! [&&_.ob-sidebar-card]:border-0! [&&_.ob-sidebar-card]:bg-transparent!",
          "[&&_.agent-list]:gap-4! [&&_.agent-list]:px-2! [&&_.agent-list]:pb-3!",
          "[&&_.sidebar-chat-group]:m-0! [&&_.sidebar-section-toggle]:min-h-7! [&&_.sidebar-section-name]:text-xs! [&&_.sidebar-section-name]:font-medium!",
          "[&&_.agent-row]:h-auto! [&&_.agent-row]:min-h-16! [&&_.agent-row]:gap-3! [&&_.agent-row]:rounded-lg! [&&_.agent-row]:p-2! [&&_.agent-row]:bg-transparent!",
          "[&&_.agent-row:hover]:bg-accent! [&&_.agent-row.agent-row-active]:bg-sidebar-row-selected! [&&_.agent-row.agent-row-active]:shadow-xs! [&&_.agent-row.agent-row-active]:ring-1! [&&_.agent-row.agent-row-active]:ring-sidebar-border!",
          "[&&_.agent-row-avatar]:size-8! [&&_.agent-row-avatar]:basis-8! [&&_.ob-sidebar-avatar]:size-8! [&&_.ob-sidebar-avatar>svg]:size-10!",
          "[&&_.agent-row-avatar_.ob-group-avatar]:[--channel-avatar-size:calc(var(--spacing)*8)]! [&&_.agent-row-avatar_.channel-avatar-picture]:size-8!",
          "[&&_.agent-row-name_strong]:text-sm! [&&_.agent-row-name_strong]:font-medium! [&&_.agent-row-preview]:text-xs! [&&_.agent-row-preview]:leading-5! [&&_.agent-row-time]:text-2xs! [&&_.agent-role-badge]:hidden!",
          "[&&_.sidebar-pinned-list]:flex! [&&_.sidebar-pinned-list]:flex-col! [&&_.sidebar-pinned-list]:gap-1! [&&_.sidebar-pinned-item]:w-full! [&&_.sidebar-pinned-item]:min-w-0! [&&_.sidebar-pinned-row.agent-row]:flex-row! [&&_.sidebar-pinned-row.agent-row]:justify-start! [&&_.sidebar-pinned-copy]:items-start! [&&_.sidebar-pinned-copy]:text-left!",
          "[&&_.ob-content-card]:rounded-none! [&&_.ob-content-card]:border-0! [&&_.ob-content-card]:bg-background! [&&_.ob-content.conversation-panel]:border-0! [&&_.ob-content.conversation-panel]:bg-background!",
          "[&&_.ob-conversation-main.hidden]:hidden! [&&_.side-panel-header]:h-13!",
          "[&&_.agent-threads-switcher]:min-w-0! [&&_.agent-threads-switcher]:max-w-full! [&&_.agent-threads-switcher>svg]:shrink-0! [&&_.agent-threads-switcher-title]:min-w-0! [&&_.agent-threads-switcher-title]:truncate!",
          "[&&_.unread-messages-banner]:rounded-none! [&&_.unread-messages-banner]:bg-primary/10! [&&_.unread-messages-banner]:text-foreground!",
        )}
      >
        <aside
          aria-label={gt("Bot chats")}
          className="relative flex min-w-[200px] shrink-0 flex-col border-r bg-sidebar"
          style={{ width }}
        >
          <div className="h-[var(--workspace-sidebar-header-height)] shrink-0" aria-hidden="true" />
          <div className="flex shrink-0 items-center gap-1 px-2 py-2">
            <div className="min-w-0 flex-1">
              <button
                type="button"
                className="flex h-8 w-full cursor-text items-center gap-2 rounded-md px-2 text-sm text-muted-foreground outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                aria-label={gt("Search conversations")}
                onClick={onOpenSearch}
              >
                <SearchIcon className="size-4 shrink-0" />
                <span className="flex-1 text-left">
                  <T>Search</T>
                </span>
                <span className="text-2xs text-muted-foreground/60" aria-hidden>
                  ⌘K
                </span>
              </button>
            </div>
            <div className="flex items-center">
              <Button
                variant="ghost-muted"
                size="icon-micro"
                aria-label={gt("Previous chat")}
                disabled={!canBack}
                onClick={onBack}
              >
                <ArrowLeftIcon />
              </Button>
              <Button
                variant="ghost-muted"
                size="icon-micro"
                aria-label={gt("Next chat")}
                disabled={!canForward}
                onClick={onForward}
              >
                <ArrowRightIcon />
              </Button>
            </div>
            <Button
              variant="ghost-muted"
              size="icon-sm"
              aria-label={gt("Create")}
              onClick={() => openCommandPalette({ open: "new-bot-chat" })}
            >
              <SquarePenIcon />
            </Button>
          </div>
          <div className="flex shrink-0 items-center justify-between px-4 pb-1.5 text-xs font-medium text-muted-foreground">
            <span>{section === "flows" ? gt("Routines") : gt("Conversations")}</span>
            <span className="text-2xs font-normal tabular-nums">
              {agents.length + (section === "flows" ? 0 : channels.length)}
            </span>
          </div>
          <div className="ob-sidebar-card">
            <OpenbotSidebar
              environmentId={environmentId}
              hostId={hostId}
              agents={agents}
              channels={section === "flows" ? [] : channels}
              {...(section !== "flows" && people ? { people } : {})}
              selectedAgentId={
                section === "chats" || section === "flows" ? (bot?.id ?? null) : null
              }
              selectedChannelId={section === "groups" ? selectedChannel : null}
              onAgent={onBot}
              onGroup={onGroup}
            />
            {loading && !agents.length && (
              <p role="status" className="p-3 text-xs">
                <T>Loading…</T>
              </p>
            )}
          </div>
          <footer className="shrink-0 px-2 pb-2 pt-3">
            <Menu>
              <MenuTrigger
                render={
                  <button
                    type="button"
                    className="flex h-8 w-full cursor-pointer items-center gap-2 rounded-md px-2 text-xs text-muted-foreground outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                    aria-label={label}
                  />
                }
              >
                <MonitorIcon className="size-3.5 shrink-0" />
                <span className="min-w-0 flex-1 truncate text-left">{label}</span>
                <ChevronDownIcon className="size-3" />
              </MenuTrigger>
              <MenuPopup align="start" side="top">
                <MenuItem onClick={() => onSection("host-settings")}>
                  <SettingsIcon />
                  <T>Host settings</T>
                </MenuItem>
                <MenuItem onClick={onRefresh}>
                  <RefreshCwIcon />
                  <T>Refresh connection</T>
                </MenuItem>
              </MenuPopup>
            </Menu>
          </footer>
          <div
            role="separator"
            tabIndex={0}
            aria-label={gt("Sidebar width")}
            aria-orientation="vertical"
            aria-valuemin={200}
            aria-valuemax={440}
            aria-valuenow={width}
            className="ob-sidebar-resize top-0! right-0!"
            onDoubleClick={() => (sharedSize ? sharedSize.reset() : setWidth(288))}
            onKeyDown={(e) => {
              if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
                e.preventDefault();
                setWidth(width + (e.key === "ArrowRight" ? 10 : -10));
              }
            }}
            onPointerDown={(e) => {
              e.preventDefault();
              e.currentTarget.setPointerCapture(e.pointerId);
            }}
            onPointerMove={(e) => {
              if (e.currentTarget.hasPointerCapture(e.pointerId)) {
                const rect = e.currentTarget.parentElement?.getBoundingClientRect();
                if (rect) setWidth(Math.max(200, Math.min(440, e.clientX - rect.left)));
              }
            }}
            onPointerUp={(e) => {
              if (e.currentTarget.hasPointerCapture(e.pointerId))
                e.currentTarget.releasePointerCapture(e.pointerId);
            }}
          />
        </aside>
        <main
          aria-label={gt("Bot workspace content")}
          className="ob-content conversation-panel"
          data-side-panel-header={sidePanelHeader ? "" : undefined}
          data-panel-maximized={sidePanelMaximized ? "" : undefined}
        >
          {sidePanelHeader}
          {showSidebar && section !== "groups" && section !== "direct" && section !== "flows" && (
            <header className="conversation-header flex h-13! shrink-0 items-center gap-3 pl-5!">
              <div className="flex min-w-0 flex-1 items-center gap-2.5">
                {section === "chats" && bot && (
                  <span className="flex size-7 shrink-0 items-center justify-center">
                    <SourceAgentAvatar agent={bot} size={24} />
                  </span>
                )}
                <h1 className="truncate text-sm font-medium">{heading}</h1>
              </div>
              {section === "chats" && bot && (
                <nav
                  aria-label={gt("Conversation tools")}
                  className="flex shrink-0 items-center gap-1"
                >
                  <ToolButton
                    label={gt("Bot tasks")}
                    pressed={view === "Tasks"}
                    onClick={() => chooseTool(view === "Tasks" ? "Chat" : "Tasks")}
                  >
                    <ListTodoIcon />
                  </ToolButton>
                  <ToolButton
                    label={gt("Files")}
                    pressed={view === "Files"}
                    onClick={() => chooseTool(view === "Files" ? "Chat" : "Files")}
                  >
                    <FilesIcon />
                  </ToolButton>
                  <Menu>
                    <MenuTrigger
                      render={
                        <Button
                          variant="ghost-muted"
                          size="icon-sm"
                          aria-label={gt("More conversation tools")}
                        />
                      }
                    >
                      <MoreHorizontalIcon />
                    </MenuTrigger>
                    <MenuPopup align="end">
                      {(
                        [
                          "Memory",
                          "Routines",
                          "Browser",
                          "Computer",
                          "Data",
                          "Vault",
                          "Settings",
                        ] as const
                      ).map((tool) => (
                        <MenuItem key={tool} onClick={() => chooseTool(tool)}>
                          {tool}
                        </MenuItem>
                      ))}
                    </MenuPopup>
                  </Menu>
                  <div className="mx-1 h-4 border-l" />
                  <ToolButton
                    label={sidePanelHeader ? gt("Close side panel") : gt("Open side panel")}
                    pressed={Boolean(sidePanelHeader)}
                    onClick={onTogglePanel}
                  >
                    <PanelRightIcon />
                  </ToolButton>
                </nav>
              )}
            </header>
          )}
          {section === "chats" && bot && view !== "Tasks" && (
            <nav
              aria-label={gt("Bot conversations")}
              className="conversation-header h-10! gap-4 border-b! border-border! pl-5!"
            >
              <div className="flex shrink-0 items-center">
                <Button
                  variant={!selectedTaskId && !newThread ? "secondary" : "ghost-muted"}
                  size="compact"
                  aria-current={!selectedTaskId && !newThread ? "page" : undefined}
                  onClick={() => {
                    onTask(null);
                    chooseTool("Chat");
                  }}
                >
                  <MessageCircleIcon />
                  <T>Main chat</T>
                </Button>
              </div>
              <div className="flex min-w-0 flex-1 items-center gap-2">
                <span className="shrink-0 text-xs text-muted-foreground">
                  <T>Task chats</T>
                </span>
                <div className="min-w-0 flex-1">
                  <OpenbotThreadTabs
                    key={bot.id}
                    tasks={tasks}
                    selectedId={selectedTaskId}
                    onSelect={onTask}
                    onRename={onRenameTask}
                    onNew={onNewThread}
                    layout={threadLayout}
                    onLayoutChange={onThreadLayout}
                    onMoveToSide={onMoveThreadToSide}
                    taskChats
                  />
                </div>
                {newThread && (
                  <span className="shrink-0 text-xs font-medium">
                    <T>New task chat</T>
                  </span>
                )}
              </div>
            </nav>
          )}
          <div
            className="ob-content-card"
            data-full-page={!showSidebar ? "" : undefined}
            data-group={section === "groups" ? "" : undefined}
          >
            {children}
          </div>
        </main>
      </div>
    </TooltipProvider>
  );
}

function ToolButton({
  label,
  pressed,
  onClick,
  children,
}: {
  label: string;
  pressed?: boolean;
  onClick: () => void;
  children: ReactNode;
}) {
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <Button
            variant="ghost-muted"
            size="icon-sm"
            aria-label={label}
            aria-pressed={pressed}
            data-pressed={pressed || undefined}
            onClick={onClick}
          />
        }
      >
        {children}
      </TooltipTrigger>
      <TooltipPopup side="bottom">{label}</TooltipPopup>
    </Tooltip>
  );
}
